    "Share {name}?" to r("{name} ይጋራ?", "{name} ይካፈል?", "{name} qoodamu?", "La wadaag {name}?", "مشاركة {name}؟"),
    "Everyone using AkAI will see its name, emoji, colours and the name you give here. You can stop sharing it any time." to r(
        "AkAIን የሚጠቀሙ ሁሉ ስሙን፣ ሺሸንፉን፣ ቀለሞቹን እና እዚህ የሚሰጡትን ስም ያያሉ። በማንኛውም ጊዜ ማጋራቱን ማቆም ይችላሉ።",
        "ኣካይ ዝጥቀሙ ኩሎም ሽሙ፣ ኢሞጂኡ፣ ሕብርታቱን ኣብዚ ትህቦ ስምን ይርእዩ። ኣብ ዝኾነ ግዜ ምክፍፋል ከተቋርጽ ትኽእል።",
        "Namni AkAI fayyadamu hundi maqaa, emojii, halluu isaa fi maqaa as kennitan ni arga. Yeroo kamiyyuu qooduu dhaabuu dandeessu.",
        "Qof kasta oo isticmaala AkAI wuxuu arki doonaa magaciisa, emoji-giisa, midabyadiisa iyo magaca aad halkan ku bixiso. Waad joojin kartaa wadaagista wakhti kasta.",
        "سيرى كل مستخدمي AkAI اسمها ورمزها وألوانها والاسم الذي تدخله هنا. يمكنك إيقاف المشاركة في أي وقت.",
    ),
    "Share" to r("አጋራ", "ኣካፍል", "Qoodi", "La wadaag", "مشاركة"),
    "Couldn't share it" to r("ማጋራት አልተቻለም", "ምክፍፋል ኣይተኻኣለን", "Qooduu hin dandeenye", "Lama wadaagi karin", "تعذّرت المشاركة"),
    "Shared. It's in Community now" to r("ተጋርቷል። አሁን በማኅበረሰብ ውስጥ አለ", "ተኻፊሉ። ሕጂ ኣብ ሕብረተሰብ ኣሎ", "Qoodameera. Amma Hawaasa keessa jira", "Waa la wadaagay. Hadda waxay ku jirtaa Bulshada", "تمت المشاركة. هي الآن في المجتمع"),
    "No connection. Try again" to r("ግንኙነት የለም። እንደገና ይሞክሩ", "ርክብ የለን። ደጊምካ ፈትን", "Walqunnamtii hin jiru. Irra deebi'ii yaali", "Xiriir ma jiro. Mar kale isku day", "لا يوجد اتصال. حاول مجددًا"),
    "No longer shared" to r("ከአሁን በኋላ አይጋራም", "ደጊም ኣይካፈልን", "Amma qoodamuu dhaabeera", "Mar dambe lama wadaagayo", "لم تعد مشتركة"),
    "Report {name}?" to r("{name} ሪፖርት ይደረግ?", "{name} ሪፖርት ይግበር?", "{name} gabaasuu?", "Ka warbixi {name}?", "الإبلاغ عن {name}؟"),
    "For an offensive name or anything that shouldn't be here. A theme reported by a few people is hidden until it's checked." to r(
        "ለአፀያፊ ስም ወይም እዚህ መሆን ለሌለበት ማንኛውም ነገር። በጥቂት ሰዎች ሪፖርት የተደረገ ገጽታ እስኪመረመር ድረስ ይደበቃል።",
        "ንሕማቕ ስም ወይ ኣብዚ ክኸውን ዘይግብኦ ዝኾነ ነገር። ብሒደት ሰባት ሪፖርት ዝተገብረ ገጽታ ክሳብ ዝምርመር ይሕብእ።",
        "Maqaa arrabsoo ykn waan as hin ta'in kamiyyuuf. Teemiin namoota muraasaan gabaafame hanga qoratamutti dhoksama.",
        "Magac xun ama wax aan halkan ku habboonayn. Qaab dad yar ay ka warbixiyeen waa la qariyaa ilaa la hubiyo.",
        "لاسم مسيء أو أي شيء لا ينبغي أن يكون هنا. تُخفى السمة التي يبلّغ عنها عدة أشخاص حتى تُراجع.",
    ),
    "Report" to r("ሪፖርት", "ሪፖርት", "Gabaasi", "Ka warbixi", "إبلاغ"),
    "Thanks for reporting it" to r("ስለ ሪፖርቱ እናመሰግናለን", "ስለ ሪፖርትካ የመስግን", "Gabaasaniif galatoomaa", "Mahadsanid warbixintaada", "شكرًا على الإبلاغ"),
    "Popular" to r("ተወዳጅ", "ዝተፈተወ", "Beekamaa", "Caan ah", "الأكثر شعبية"),
    "New" to r("አዲስ", "ሓድሽ", "Haaraa", "Cusub", "جديد"),
    "Themes people made and shared. Tap one to add it to Mine; long-press to report it. To share yours, long-press it under Mine." to r(
        "ሰዎች የሠሩትና ያጋሩት ገጽታዎች። ወደ የእኔ ለመጨመር አንዱን ይንኩ፤ ሪፖርት ለማድረግ ረጅም ይጫኑ። የእርስዎን ለማጋራት በየእኔ ውስጥ ረጅም ይጫኑት።",
        "ሰባት ዝሰርሑን ዘካፈሉን ገጽታታት። ናብ ናተይ ንምውሳኽ ሓደ ትንክፍ፤ ሪፖርት ንምግባር ነዊሕ ጠዊ። ናትካ ንምክፋል ኣብ ናተይ ነዊሕ ጠዊ።",
        "Teemiiwwan namoonni hojjetanii qoodan. Gara kan koo dabaluuf tokko tuqi; gabaasuuf yeroo dheeraa tuqi. Kan keessan qoodduuf kan koo jalatti yeroo dheeraa tuqi.",
        "Qaababka dadku sameeyeen oo wadaageen. Taabo mid si aad ugu darto Kuwayga; cadaadis dheer si aad u warbixiso. Si aad kaaga u wadaagto, ku hay Kuwayga hoostiisa.",
        "سمات صنعها الناس وشاركوها. اضغط على واحدة لإضافتها إلى سماتي؛ واضغط مطولًا للإبلاغ. لمشاركة سماتك اضغط مطولًا عليها ضمن سماتي.",
    ),
    "Try again" to r("እንደገና ሞክር", "ደጊምካ ፈትን", "Irra deebi'ii yaali", "Mar kale isku day", "حاول مجددًا"),
    "Loading…" to r("በመጫን ላይ…", "ይጽዕን ኣሎ…", "Fe'aa jira…", "Waa la rarayaa…", "جارٍ التحميل…"),
    "Nothing shared yet. Be the first: long-press one of your themes under Mine and choose Share." to r(
        "እስካሁን ምንም አልተጋራም። የመጀመሪያው ይሁኑ፤ በየእኔ ውስጥ ካሉ ገጽታዎችዎ አንዱን ረጅም ይጫኑና አጋራ ይምረጡ።",
        "ክሳብ ሕጂ ዝተኻፈለ የለን። ቀዳማይ ኹን፤ ኣብ ናተይ ካብ ዘለዉ ገጽታታትካ ሓደ ነዊሕ ጠዊ ኣካፍል ምረጽ።",
        "Ammaaf homaa hin qoodamne. Isa jalqabaa ta'i: teemii kee tokko kan koo jalatti yeroo dheeraa tuqiitii Qoodi filadhu.",
        "Weli waxba lama wadaagin. Noqo kan ugu horreeya: ku hay mid ka mid ah qaababkaaga Kuwayga hoostiisa oo dooro La wadaag.",
        "لم تتم مشاركة أي شيء بعد. كن الأول: اضغط مطولًا على إحدى سماتك ضمن سماتي واختر مشاركة.",
    ),
    "Load more" to r("ተጨማሪ ጫን", "ተወሳኺ ጸዓን", "Dabalataa fe'i", "Rar kuwo kale", "تحميل المزيد"),
    "Themes" to r("ገጽታዎች", "ገጽታታት", "Teemiiwwan", "Qaababka", "السمات"),
    "{n} themes. Tap one to use it; long-press to customize it." to r("{n} ገጽታዎች። ለመጠቀም አንዱን ይንኩ፤ ለማበጀት ረጅም ይጫኑ።", "{n} ገጽታታት። ንምጥቃም ሓደ ትንክፍ፤ ንምምቻች ነዊሕ ጠዊ።", "Teemiiwwan {n}. Fayyadamuuf tokko tuqi; qopheessuuf yeroo dheeraa tuqi.", "{n} qaab. Taabo mid si aad u isticmaasho; cadaadis dheer si aad u hagaajiso.", "{n} سمة. اضغط على واحدة لاستخدامها؛ واضغط مطولًا لتخصيصها."),
    "All" to r("ሁሉም", "ኩሉ", "Hunda", "Dhammaan", "الكل"),
    "Mine" to r("የእኔ", "ናተይ", "Kan koo", "Kuwayga", "سماتي"),
