    "Football" to r("እግር ኳስ", "ኩዕሶ እግሪ", "Kubbaa miilaa", "Kubadda cagta", "كرة القدم"),
    "MINE " to r("የእኔ ", "ናተይ ", "KAN KOO ", "KUWAYGA ", "سماتي "),
    "LIVE" to r("ሕያው", "ህያው", "JIRAATAA", "NOOL", "حية"),
    "Create theme" to r("ገጽታ ፍጠር", "ገጽታ ፍጠር", "Teemii uumi", "Samee qaab", "إنشاء سمة"),
    "Themes you make show up here. Tap Create theme, or long-press any theme to start from its colours." to r(
        "የሚሠሯቸው ገጽታዎች እዚህ ይታያሉ። ገጽታ ፍጠርን ይንኩ፣ ወይም ከቀለሞቹ ለመጀመር ማንኛውንም ገጽታ ረጅም ይጫኑ።",
        "ትሰርሖም ገጽታታት ኣብዚ ይርአዩ። ገጽታ ፍጠር ትንክፍ፣ ወይ ካብ ሕብርታቱ ንምጅማር ዝኾነ ገጽታ ነዊሕ ጠዊ።",
        "Teemiiwwan hojjettan as mul'atu. Teemii uumi tuqi, ykn halluu isaa irraa jalqabuuf teemii kamiyyuu yeroo dheeraa tuqi.",
        "Qaababka aad samayso halkan ayay ka muuqdaan. Taabo Samee qaab, ama ku hay qaab kasta si aad ugu bilowdo midabyadiisa.",
        "السمات التي تصنعها تظهر هنا. اضغط على إنشاء سمة، أو اضغط مطولًا على أي سمة للبدء من ألوانها.",
    ),

    // Sticker marketplace
    "No connection. Check the internet and try again" to r("ግንኙነት የለም። ኢንተርኔትዎን ያረጋግጡና እንደገና ይሞክሩ", "ርክብ የለን። ኢንተርኔትካ ኣረጋግጽ ደጊምካ ፈትን", "Walqunnamtii hin jiru. Intarneetii mirkaneessiitii irra deebi'ii yaali", "Xiriir ma jiro. Hubi internetka oo mar kale isku day", "لا يوجد اتصال. تحقق من الإنترنت وحاول مجددًا"),
    "The Sticker Marketplace is unavailable right now" to r("የተለጣፊ ገበያው አሁን አይገኝም", "ዕዳጋ ስቲከር ሕጂ ኣይርከብን", "Gabaan stikeroota amma hin argamu", "Suuqa stickers-ka hadda lama heli karo", "سوق الملصقات غير متاح الآن"),
    "Install the packs you like. Only installed packs are downloaded, so Akai stays small." to r("የሚወዷቸውን ጥቅሎች ይጫኑ። የተጫኑት ብቻ ይወርዳሉ፣ ስለዚህ አካይ ትንሽ ሆኖ ይቆያል።", "ዝፈተውካዮም ጥቕላላት ጸዓን። ዝተጻዕኑ ጥራይ ይወርዱ፣ ስለዚ ኣካይ ንእሽተይ ይጸንሕ።", "Kuusaawwan jaallattan fe'i. Kan fe'aman qofa buufamu, kanaaf Akai xiqqoo ta'a.", "Rakib xirmooyinka aad jeceshahay. Kuwa la rakibay oo keliya ayaa la soo dejiyaa, sidaas darteed Akai wuu yaraadaa.", "ثبّت الحزم التي تعجبك. تُنزَّل المثبّتة فقط، لذا يبقى Akai صغيرًا."),
    "Search packs" to r("ጥቅሎችን ፈልግ", "ጥቕላላት ድለ", "Kuusaawwan barbaadi", "Raadi xirmooyin", "ابحث عن الحزم"),
    "Show more" to r("ተጨማሪ አሳይ", "ተወሳኺ ኣርኢ", "Dabalataa agarsiisi", "Muuji kuwo kale", "عرض المزيد"),
    "Have a link?" to r("አገናኝ አለዎት?", "ሊንክ ኣለካ?", "Linkii qabduu?", "Xiriir ma haysaa?", "هل لديك رابط؟"),
    "Add any Telegram pack" to r("ማንኛውንም የቴሌግራም ጥቅል ጨምር", "ዝኾነ ጥቕላል ቴሌግራም ወስኽ", "Kuusaa Teleegraamii kamiyyuu dabali", "Ku dar xirmo Telegram kasta", "أضف أي حزمة تيليجرام"),
    "Paste a t.me/addstickers or t.me/addemoji link to install a pack that isn't listed here." to r("እዚህ ያልተዘረዘረ ጥቅል ለመጫን የt.me/addstickers ወይም t.me/addemoji አገናኝ ይለጥፉ።", "ኣብዚ ዘይተዘርዘረ ጥቕላል ንምጽዓን ሊንክ t.me/addstickers ወይ t.me/addemoji ለጥፍ።", "Kuusaa as hin tarreeffamne fe'uuf linkii t.me/addstickers ykn t.me/addemoji maxxansi.", "Ku dheji xiriirka t.me/addstickers ama t.me/addemoji si aad u rakibto xirmo aan halkan lagu qorin.", "الصق رابط t.me/addstickers أو t.me/addemoji لتثبيت حزمة غير مدرجة هنا."),
    "No emoji packs yet. Check back soon." to r("እስካሁን የሺሸንፍ ጥቅሎች የሉም። በቅርቡ ይመለሱ።", "ክሳብ ሕጂ ጥቕላላት ኢሞጂ የለን። ኣብ ቀረባ ተመለስ።", "Ammaaf kuusaan emojii hin jiru. Dhiyootti deebi'i.", "Weli ma jiraan xirmooyin emoji ah. Dhawaan ku soo noqo.", "لا توجد حزم رموز بعد. عُد قريبًا."),
    "No sticker packs yet. Check back soon." to r("እስካሁን የተለጣፊ ጥቅሎች የሉም። በቅርቡ ይመለሱ።", "ክሳብ ሕጂ ጥቕላላት ስቲከር የለን። ኣብ ቀረባ ተመለስ።", "Ammaaf kuusaan stikeera hin jiru. Dhiyootti deebi'i.", "Weli ma jiraan xirmooyin stickers ah. Dhawaan ku soo noqo.", "لا توجد حزم ملصقات بعد. عُد قريبًا."),
